parameters.jsCode:
const execution = $json;
return [{
  json: {
    incident_id: 'inc_' + Date.now(),
    workflow_name: execution.workflow ? execution.workflow.name : 'ai-sdr-inbound-closer',
    failed_at: new Date().toISOString(),
    error_message: execution.execution ? execution.execution.error.message : 'Unknown execution failure',
    payload_snippet: execution.execution ? JSON.stringify(execution.execution.data).slice(0, 500) : 'N/A'
  }
}];

